#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=17
REPOSITORY_ROOT=$(cd "$(dirname "$0")/../.." && pwd)
KEEPLORE_TOOLS=/usr/local/libexec/keeplore
KEEPLORE_CONFIGURATION=/etc/voice-agent/keeplore.conf
KEEPLORE_REPOSITORY=JacobStephens2/keeplore
PWA_URL=https://voice.stephens.page
MERGE_COMMIT=""

keeplore_gh() {
  gh api -H 'Accept: application/vnd.github+json' "$@"
}

require_gh() {
  if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
    warn "GitHub CLI is required for this stage. Authenticate with: gh auth login"
    exit 1
  fi
}

read_configuration_value() {
  sudo grep -E "^$1=" "$KEEPLORE_CONFIGURATION" 2>/dev/null | tail -n1 | cut -d= -f2- || true
}

if [[ ! -e /opt/voice-agent ]]; then
  warn "Run this wizard on the Agent Host so the Keeplore checkout, Promotion, and health can be checked."
  exit 1
fi

banner "Keeplore onboarding with a harmless Human Merge"

stage "Register the Keeplore deployment boundaries"
say "Promotion reads a root-owned registration; nothing in a repository can widen it."
say "Keeplore is PHP served from files by Apache, so a Release is linted rather than built."
ask LIVE_CHECKOUT "Absolute path of the live Keeplore checkout [/var/www/keeplore.app]"
LIVE_CHECKOUT=${LIVE_CHECKOUT:-/var/www/keeplore.app}
ask HEALTH_URL "Keeplore health URL [https://api.keeplore.app/api/health]"
HEALTH_URL=${HEALTH_URL:-https://api.keeplore.app/api/health}
ask PUBLIC_HEALTH_URL "Second health URL to verify (blank to skip)"
ask VERIFICATION_COMMAND "Declared Keeplore verification command [vendor/bin/phpunit]"
VERIFICATION_COMMAND=${VERIFICATION_COMMAND:-vendor/bin/phpunit}
LINT_COMMAND="find . -name '*.php' -not -path './vendor/*' -print0 | xargs -0 -r -n1 php -l"
BUILD_COMMAND=$LINT_COMMAND
PREFLIGHT_COMMAND=$LINT_COMMAND
DOCUMENT_ROOT_UI=$LIVE_CHECKOUT/ui
DOCUMENT_ROOT_API=$LIVE_CHECKOUT/api
SHARED_ROOT=/opt/keeplore/shared
SHARED_PATHS=private/environment_variables.php,private/vendor,database/backups,logs
sudo install -d -o root -g root -m 0755 /etc/voice-agent "$KEEPLORE_TOOLS"
sudo tee "$KEEPLORE_CONFIGURATION" >/dev/null <<CONFIGURATION
KEEPLORE_REPOSITORY=$KEEPLORE_REPOSITORY
KEEPLORE_LIVE_CHECKOUT=$LIVE_CHECKOUT
KEEPLORE_RELEASE_ROOT=/opt/keeplore/releases
KEEPLORE_CURRENT_LINK=/opt/keeplore/current
KEEPLORE_SOURCE_MIRROR=/var/lib/keeplore-source/repository.git
KEEPLORE_DOCUMENT_ROOT_UI=$DOCUMENT_ROOT_UI
KEEPLORE_DOCUMENT_ROOT_API=$DOCUMENT_ROOT_API
KEEPLORE_SHARED_ROOT=$SHARED_ROOT
KEEPLORE_SHARED_PATHS=$SHARED_PATHS
KEEPLORE_RELOAD_COMMAND=/usr/sbin/apache2ctl graceful
KEEPLORE_HEALTH_URL=$HEALTH_URL
KEEPLORE_PUBLIC_HEALTH_URL=$PUBLIC_HEALTH_URL
KEEPLORE_RETAINED_RELEASES=2
KEEPLORE_BUILD_COMMAND=$BUILD_COMMAND
KEEPLORE_VERIFICATION_COMMAND=$VERIFICATION_COMMAND
KEEPLORE_PREFLIGHT_COMMAND=$PREFLIGHT_COMMAND
CONFIGURATION
sudo chown root:root "$KEEPLORE_CONFIGURATION"
sudo chmod 0644 "$KEEPLORE_CONFIGURATION"
for script in keeplore-config.sh inspect-keeplore.sh install-keeplore-release.sh \
  keeplore-health.sh promote-keeplore-main.sh promote-keeplore-release.sh \
  prune-keeplore-releases.sh reconcile-keeplore-merges.sh \
  collect-keeplore-repository-policy.sh record-keeplore-bypass-attestation.sh \
  repoint-keeplore-vhosts.sh; do
  sudo install -o root -g root -m 0755 \
    "$REPOSITORY_ROOT/ops/keeplore/$script" "$KEEPLORE_TOOLS/$script"
done
# The Keeplore tools authenticate as the GitHub App themselves, so the App
# credentials helpers sit beside them rather than being resolved out of the
# release orchestrator's directory.
for script in github-app-jwt.sh github-source-token.sh; do
  sudo install -o root -g root -m 0755 \
    "$REPOSITORY_ROOT/ops/release/$script" "$KEEPLORE_TOOLS/$script"
done
note "Root-owned Keeplore registration and release tools are installed."
step "Ensure the restricted deploy account may run only $KEEPLORE_TOOLS/promote-keeplore-main.sh through passwordless sudo."
pause "Press Enter once that sudoers rule is in place."

stage "Revalidate the live Keeplore checkout read-only"
say "Nothing pulls, branches, builds, or deploys until this inspection is clean."
if sudo "$KEEPLORE_TOOLS/inspect-keeplore.sh"; then
  note "The live checkout is clean and tracks the registered repository."
else
  warn "The inspection reported live work that only you can reconcile."
fi

stage "Reconcile and preserve live uncommitted work"
say "Automation never stashes, resets, or discards your live work. You decide what happens to it."
step "Commit it, push it to a branch, or stash it deliberately in $LIVE_CHECKOUT."
while ! sudo "$KEEPLORE_TOOLS/inspect-keeplore.sh" >/dev/null 2>&1; do
  sudo "$KEEPLORE_TOOLS/inspect-keeplore.sh" || true
  pause "Press Enter to re-inspect after reconciling the live working tree."
done
note "The live Keeplore working tree is reconciled and preserved."

stage "Move Keeplore's runtime state into the shared root"
say "A Release is built from Git, so it carries no database credentials, private dependencies, backups, or logs."
say "Those live in the shared root and are linked into every Release, which also keeps secrets out of Releases."
sudo install -d -o root -g root -m 0755 "$SHARED_ROOT"
for entry in ${SHARED_PATHS//,/ }; do
  source_path="$LIVE_CHECKOUT/$entry"
  target_path="$SHARED_ROOT/$entry"
  if sudo test -e "$target_path"; then
    note "Shared state already holds $entry"
    continue
  fi
  if ! sudo test -e "$source_path"; then
    warn "The live checkout has no $entry; create it in $SHARED_ROOT before promoting."
    SKIPPED+=("Shared Keeplore state $entry")
    continue
  fi
  sudo install -d -o root -g root -m 0755 "$(dirname "$target_path")"
  sudo cp -a "$source_path" "$target_path"
  note "Copied $entry into the shared root (the live checkout keeps its copy)."
done
sudo ls -la "$SHARED_ROOT" | head -8
confirm "Does the shared root hold Keeplore's credentials, private dependencies, backups, and logs?" || exit 1

stage "Enroll Keeplore with a Fresh Passkey Action"
open_url "$PWA_URL"
step "Sign in with a passkey, then choose “Perform Fresh Passkey Action”."
step "Choose “Inspect live Keeplore checkout”, confirm the repository, branch, checkout, serving path, and verification."
step "Record how you reconciled the live work, then choose “Enroll Keeplore”."
step "Confirm voice, repository content, and an ordinary Trusted Browser Session cannot enroll it."
pause "Press Enter after the PWA shows the Keeplore registration revision."

stage "Require pull requests on the Keeplore production branch"
require_gh
open_url "https://github.com/$KEEPLORE_REPOSITORY/settings/rules"
step "Create a ruleset targeting main that requires a pull request, requires the keeplore-verification check, and blocks force pushes and deletion."
step "Grant no bypass actors. The coding agent and its GitHub App must not be able to bypass the rules."
pause "Press Enter after the ruleset is active."
protection=$(keeplore_gh "repos/$KEEPLORE_REPOSITORY/rules/branches/main" 2>/dev/null || printf '[]')
if jq -e 'map(.type) | index("pull_request") and index("non_fast_forward") and index("deletion")' \
  <<<"$protection" >/dev/null 2>&1; then
  note "GitHub reports pull-request, force-push, and deletion rules on main."
else
  warn "GitHub does not yet report all required rules on main. Fix the ruleset before continuing."
  confirm "Continue anyway?" || exit 1
fi

stage "Add minimal Keeplore CI as the required check"
say "The declared verification runs in CI and reports the required keeplore-verification check."
note "Templates: $REPOSITORY_ROOT/ops/keeplore/github/"
say "The CI job must run exactly the declared verification: $VERIFICATION_COMMAND"
step "Open a harmless pull request in $KEEPLORE_REPOSITORY adding:"
step "  .github/workflows/keeplore-verification.yml  (the required check; set its run step to $VERIFICATION_COMMAND)"
step "  .github/workflows/promote-keeplore.yml       (enqueues verified Human Merges)"
step "This is the harmless change the Human Merge will promote. It must not change Keeplore behaviour."
ask PR_NUMBER "Keeplore pull-request number"
[[ $PR_NUMBER =~ ^[1-9][0-9]*$ ]] || { warn "A pull-request number is required."; exit 1; }
open_url "https://github.com/$KEEPLORE_REPOSITORY/pull/$PR_NUMBER"
pause "Press Enter once keeplore-verification passes on the pull request."

stage "Install the least-privilege GitHub App"
say "The App needs contents, pull requests, and checks only: no administration and no ruleset bypass."
open_url "https://github.com/settings/installations"
step "Install the Voice Agent App on $KEEPLORE_REPOSITORY alone."
step "Grant contents: read and write, pull requests: read and write, checks: read. Grant nothing else."
pause "Press Enter after the installation is limited to that repository and those permissions."
step "Set the repository deploy variables and secrets used by promote-keeplore.yml:"
step "  gh variable set KEEPLORE_DEPLOY_HOST --repo $KEEPLORE_REPOSITORY --body stephens.page"
step "  gh variable set KEEPLORE_DEPLOY_USER --repo $KEEPLORE_REPOSITORY --body <restricted user>"
step "  gh secret set KEEPLORE_DEPLOY_KEY_B64 --repo $KEEPLORE_REPOSITORY"
step "  gh secret set KEEPLORE_KNOWN_HOSTS_B64 --repo $KEEPLORE_REPOSITORY"
pause "Press Enter once the deploy variables and secrets exist."

stage "Activate the Keeplore Deployment Contract"
say "The contract is versioned and activated only by a Fresh Passkey Action. Repository content cannot activate or widen it."
open_url "$PWA_URL"
step "Perform a Fresh Passkey Action, then choose “Activate Keeplore Deployment Contract”."
step "Confirm the Release root sits outside the live checkout and the health path and expected status are correct."
pause "Press Enter after the PWA reports the active contract revision."

stage "Human Merge the harmless pull request"
require_gh
open_url "https://github.com/$KEEPLORE_REPOSITORY/pull/$PR_NUMBER"
step "Merge the pull request as your authenticated GitHub user. Do not push to main and do not let a bot merge."
pause "Press Enter after the merge."
MERGE_COMMIT=$(gh pr view "$PR_NUMBER" --repo "$KEEPLORE_REPOSITORY" \
  --json state,mergeCommit --jq 'if .state == "MERGED" then .mergeCommit.oid else empty end' 2>/dev/null || true)
while [[ ! $MERGE_COMMIT =~ ^[0-9a-f]{40}$ ]]; do
  ask MERGE_COMMIT "Paste the 40-character Human Merge commit SHA:"
  MERGE_COMMIT=${MERGE_COMMIT//[$'\t\r\n ']/}
done
note "Human Merge commit is $MERGE_COMMIT"
while true; do
  active=none
  if [[ -L /opt/keeplore/current ]]; then
    active=$(basename "$(readlink -f /opt/keeplore/current)")
  fi
  if [[ $active == "$MERGE_COMMIT" ]]; then
    note "Keeplore holds immutable Release $active."
    break
  fi
  note "Active Keeplore Release is $active. Waiting for $MERGE_COMMIT."
  confirm "Promote it now from this host instead of waiting for the workflow?" && \
    sudo "$KEEPLORE_TOOLS/promote-keeplore-main.sh" "$MERGE_COMMIT" || true
  pause "Press Enter to re-check Promotion."
done
sudo "$KEEPLORE_TOOLS/keeplore-health.sh"
retained=$(sudo find /opt/keeplore/releases -mindepth 1 -maxdepth 1 -type d | wc -l | tr -d ' ')
note "Keeplore retains $retained Release(s) for rollback."

stage "Serve Keeplore from the active Release"
say "Apache still serves the live checkout, so no Promotion is real yet."
say "This repoints keeplore.app and api.keeplore.app at $SHARED_ROOT's sibling /opt/keeplore/current."
step "The previous vhost files are backed up and restored automatically if configtest, the reload, or health fails."
confirm "Cut Keeplore over to the released document roots now?" || exit 1
sudo "$KEEPLORE_TOOLS/repoint-keeplore-vhosts.sh"
sudo "$KEEPLORE_TOOLS/keeplore-health.sh"
note "Keeplore is served from the active Release."

stage "Prove rollback with a controlled failed verification"
say "The drill promotes the retained Release as a candidate whose verification is forced to fail."
say "Nothing in the registration or the health check is edited, and live data is never touched."
warn "Keeplore restarts twice during the drill."
serving_release=$(basename "$(readlink -f /opt/keeplore/current)")
retained_release=$(sudo find /opt/keeplore/releases -mindepth 1 -maxdepth 1 -type d \
  -printf '%T@\t%p\n' | sort -rn | cut -f2- | xargs -r -n1 basename \
  | grep -vx "$serving_release" | head -n1)
if [[ ! $retained_release =~ ^[0-9a-f]{40}$ ]]; then
  warn "No retained Release exists yet, so rollback cannot be proven from this Human Merge alone."
  SKIPPED+=("Rollback drill — re-run this stage after a second Keeplore Human Merge")
else
  confirm "Run the controlled rollback drill against retained Release $retained_release?" || exit 1
  if sudo env KEEPLORE_VERIFICATION_DRILL=1 \
    "$KEEPLORE_TOOLS/promote-keeplore-release.sh" "$retained_release"; then
    warn "The Promotion reported success while its verification was forced to fail. Stop and fix promote-keeplore-release.sh."
    exit 1
  fi
  restored=$(basename "$(readlink -f /opt/keeplore/current)")
  if [[ $restored != "$serving_release" ]]; then
    warn "Rollback restored $restored, not the serving Release $serving_release."
    exit 1
  fi
  sudo "$KEEPLORE_TOOLS/keeplore-health.sh"
  note "The failed candidate rolled back to $serving_release, which verified healthy."
fi
sudo tail -n 3 /var/lib/keeplore-promotions/attempts.jsonl || true
say "Your live checkout is untouched by the drill:"
sudo "$KEEPLORE_TOOLS/inspect-keeplore.sh" | grep -E 'headCommit|uncommittedPaths'

stage "Confirm reconciliation is idempotent"
say "Reconciliation must recognize the Human Merge already promoted and enqueue nothing."
sudo "$KEEPLORE_TOOLS/reconcile-keeplore-merges.sh"
note "Reconciliation reported no missed Human Merge."

stage "Record the repository policy the Voice Agent can see"
say "The Voice Agent assesses only what its own GitHub credentials can observe: it holds no repository administration."
sudo "$KEEPLORE_TOOLS/collect-keeplore-repository-policy.sh"
sudo tail -n 2 /var/lib/keeplore-promotions/repository-policy.jsonl
confirm "Do the observations name the pull-request, status-check, force-push, and deletion rules, and contents, pull requests, checks, and metadata only?" || exit 1

stage "Attest the production branch's bypass actors"
require_gh
say "GitHub discloses a ruleset's bypass actors only to an actor that may write the ruleset."
say "The Voice Agent's App must never hold that, so this one boundary is yours to establish."
step "This reads the rulesets on main with your own authenticated gh and records what it finds."
sudo -E "$KEEPLORE_TOOLS/record-keeplore-bypass-attestation.sh"
say "An empty bypass-actor list is the finding you want. Any actor named there is a violation the Evidence Record will carry."
confirm "Did the attestation report zero bypass actors?" || exit 1

stage "Keep the repository-policy observations fresh"
say "An observation older than a week no longer describes the repository, so the Voice Agent stops claiming it."
for unit in keeplore-repository-policy.service keeplore-repository-policy.timer; do
  sudo install -o root -g root -m 0644 \
    "$REPOSITORY_ROOT/ops/systemd/$unit" "/etc/systemd/system/$unit"
done
sudo systemctl daemon-reload
sudo systemctl enable --now keeplore-repository-policy.timer
sudo systemctl list-timers keeplore-repository-policy.timer --no-pager || true
note "The collector re-observes the repository policy daily."

stage "Inspect the Evidence Record"
open_url "$PWA_URL"
step "Open the Keeplore onboarding Evidence Record."
step "Confirm it shows the registration revision, Deployment Contract revision, branch-rule and GitHub App assessments, merge provenance, Release, Promotion Attempt, health evidence, and rollback result."
step "Confirm no secrets, tokens, raw logs, or Keeplore application data appear."
ask TASK_URL "Authenticated Evidence Record task link:"
confirm "Does the Evidence Record show a complete, healthy Keeplore onboarding?" || exit 1
say "Issue #12 stays open until you close it. Draft comment:"
printf '\n  Keeplore is onboarded. The harmless Human Merge `%s` promoted to an immutable Release\n' "$MERGE_COMMIT"
printf '  under /opt/keeplore/releases, verified healthy, and the prior Release was retained.\n'
printf '\n  Evidence Record: %s\n' "$TASK_URL"
printf '  Rollback was proven by a controlled failed verification; reconciliation stayed idempotent.\n\n'
note "Close https://github.com/JacobStephens2/voice-agent/issues/12 with that comment when you are satisfied."

finish
